files.content:
body {
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #80d994;
}

h2,
h3,
p,
ul {
  margin: 0;
}

img {
  display: block;
  max-inline-size: 100%;
}

ul {
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
}

.section:not(:last-child) {
  margin-block-end: 2em;
}

.section-title {
  margin-block-end: 0.5em;
  font-size: 45px;
  text-transform: uppercase;
}

.cards-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 20px;
}

.cards-list__link {
  display: block;
  text-decoration: none;
}

.cards-list__link:hover {
  box-shadow: 8px 8px 0 var(--shadow-color, #000);
}

.card {
  block-size: 100%;
  min-block-size: 700px;
  border: 1px solid var(--border-color, #000);
  background-color: var(--card-bg-color, #fff);
}

.card__image {
  inline-size: 100%;
  border-block-end: 1px solid var(--border-color, #000);
  aspect-ratio: 1 / 1;
}

.card__title {
  font-weight: 800;
  font-size: 28px;
  text-transform: uppercase;
}

.card__description {
  display: flex;
  flex-direction: column;
  gap: 10px;
  block-size: 100%;
  padding: 20px;
}

.price {
  font-weight: 800;
}

.soon {
  --card-bg-color: #feafe8;
  --border-color: #5f0dee;
  --shadow-color: #5f0dee;
}
